from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
TARGET = ROOT / "toda_group_proof_narrative_reasons.py"
TEST = ROOT / "tests" / "test_phase150_rc4_closure_reason_visibility.py"
START = "def build_toda_group_proof_narrative_reason_sidecar(\n"
REPLACEMENT = 'def build_toda_group_proof_narrative_reason_sidecar(\n  presentation: TodaGroupProofPresentation,\n  semantic_sidecar: TodaGroupProofNarrativeSemanticSidecar,\n) -> TodaGroupProofNarrativeReasonSidecar:\n  if not isinstance(\n    presentation,\n    TodaGroupProofPresentation,\n  ):\n    raise TypeError(\n      "presentation must be a "\n      "TodaGroupProofPresentation"\n    )\n\n  if not isinstance(\n    semantic_sidecar,\n    TodaGroupProofNarrativeSemanticSidecar,\n  ):\n    raise TypeError(\n      "semantic_sidecar must be a "\n      "TodaGroupProofNarrativeSemanticSidecar"\n    )\n\n  if semantic_sidecar.presentation is not presentation:\n    raise ValueError(\n      "semantic_sidecar must belong to presentation"\n    )\n\n  reasons = []\n  reference_applications_by_step_id = {}\n  visible_step_ids = {\n    id(node.proof_step)\n    for node in presentation.nodes\n  }\n\n  def append_if_visible(\n    reason: TodaGroupProofNarrativeReason,\n  ) -> None:\n    reason_steps = (\n      reason.premise_steps\n      + (reason.conclusion_step,)\n    )\n    if not all(\n      id(proof_step) in visible_step_ids\n      for proof_step in reason_steps\n    ):\n      return\n    reasons.append(reason)\n\n  for application in semantic_sidecar.reference_application_semantics:\n    reference_applications_by_step_id.setdefault(\n      id(application.dependent_step),\n      [],\n    ).append(application)\n\n  for dependency in semantic_sidecar.dependency_semantics:\n    if (\n      dependency.role\n      is not TodaGroupProofNarrativeDependencySemanticRole\n      .PRECONDITION_FOR_DEFINITION\n    ):\n      continue\n\n    matching_applications = reference_applications_by_step_id.get(\n      id(dependency.dependent_step),\n      (),\n    )\n    reference_application = (\n      matching_applications[0]\n      if len(matching_applications) == 1\n      else None\n    )\n\n    append_if_visible(\n      TodaGroupProofNarrativeReason(\n        kind=(\n          TodaGroupProofNarrativeReasonKind\n          .DEFINITION_APPLICABILITY\n        ),\n        premise_steps=(dependency.prerequisite_step,),\n        conclusion_step=dependency.dependent_step,\n        reference_application=reference_application,\n      )\n    )\n\n  for node in presentation.nodes:\n    exactness_reason = _exactness_to_map_property_reason(\n      node.proof_step\n    )\n    if exactness_reason is not None:\n      append_if_visible(exactness_reason)\n\n    multiple_order_reason = _multiple_relation_to_order_reason(\n      node.proof_step\n    )\n    if multiple_order_reason is not None:\n      append_if_visible(multiple_order_reason)\n\n    final_group_structure_reason = _final_group_structure_reason(\n      node.proof_step\n    )\n    if final_group_structure_reason is not None:\n      append_if_visible(final_group_structure_reason)\n\n  return TodaGroupProofNarrativeReasonSidecar(\n    presentation=presentation,\n    reasons=tuple(reasons),\n  )\n'
TEST_CONTENT = 'from tests.test_phase143_19_method_evidence import (\n  _method_evidence_data,\n)\nfrom toda_group_proof_narrative_reasons import (\n  TodaGroupProofNarrativeReasonKind,\n  build_toda_group_proof_narrative_reason_sidecar,\n)\n\n\ndef _reason_sidecar(n, k):\n  presentation, _, semantic_sidecar, _ = (\n    _method_evidence_data(n, k)\n  )\n  return (\n    presentation,\n    build_toda_group_proof_narrative_reason_sidecar(\n      presentation,\n      semantic_sidecar,\n    ),\n  )\n\n\ndef test_phase150_rc4_closure_pi10_4_filters_hidden_recursive_reason_steps():\n  presentation, reason_sidecar = _reason_sidecar(4, 6)\n  visible_step_ids = {\n    id(node.proof_step)\n    for node in presentation.nodes\n  }\n\n  for reason in reason_sidecar.reasons:\n    assert id(reason.conclusion_step) in visible_step_ids\n    assert all(\n      id(premise) in visible_step_ids\n      for premise in reason.premise_steps\n    )\n\n  internal_pi6_step = presentation.nodes[17].proof_step\n  assert not any(\n    (\n      reason.kind\n      is TodaGroupProofNarrativeReasonKind.FINAL_GROUP_STRUCTURE\n    )\n    and reason.conclusion_step is internal_pi6_step\n    for reason in reason_sidecar.reasons\n  )\n\n\ndef test_phase150_rc4_closure_pi6_3_keeps_visible_final_group_reason():\n  _, reason_sidecar = _reason_sidecar(3, 3)\n  final_reasons = tuple(\n    reason\n    for reason in reason_sidecar.reasons\n    if (\n      reason.kind\n      is TodaGroupProofNarrativeReasonKind.FINAL_GROUP_STRUCTURE\n    )\n  )\n  assert len(final_reasons) == 1\n\n\ndef test_phase150_rc4_closure_pi8_5_keeps_visible_final_group_reason():\n  _, reason_sidecar = _reason_sidecar(5, 3)\n  final_reasons = tuple(\n    reason\n    for reason in reason_sidecar.reasons\n    if (\n      reason.kind\n      is TodaGroupProofNarrativeReasonKind.FINAL_GROUP_STRUCTURE\n    )\n  )\n  assert len(final_reasons) == 1\n'

def main() -> None:
  text = TARGET.read_text(encoding="utf-8")
  start = text.find(START)
  if start < 0:
    raise RuntimeError("reason sidecar builder was not found")
  TARGET.write_text(text[:start] + REPLACEMENT, encoding='utf-8')
  TEST.write_text(TEST_CONTENT, encoding='utf-8')
  print("RC4 closure visibility repair applied.")
  print("Changed: toda_group_proof_narrative_reasons.py::build_toda_group_proof_narrative_reason_sidecar")
  print("Added: tests/test_phase150_rc4_closure_reason_visibility.py")

if __name__ == "__main__":
  main()
